import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: '2026-01-01T00:00:00.000Z'}],
  };
}

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      for (const chunk of rounds[round++] ?? []) yield chunk;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const registryReturning = (): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register({name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}}, async () => ({
    result: 'found it',
  }));
  return registry;
};

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {}}};

describe('Turn Usage Reporting', () => {
  it('reports usage covering every provider call in a multi-round turn', async () => {
    let seenUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        seenUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 2, totalTokens: 12}}],
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 15, outputTokens: 5, totalTokens: 20}}],
        [
          {type: 'text', text: 'done'},
          {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 20, outputTokens: 10, totalTokens: 30}},
        ],
      ]),
      promptBuilder,
      registryReturning(),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seenUsage).toEqual({
      inputTokens: 45,
      outputTokens: 17,
      totalTokens: 62,
    });
  });

  it('accumulates usage safely when some rounds report no usage', async () => {
    let seenUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        seenUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 2, totalTokens: 12}}],
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use'}], // No usage this round
        [
          {type: 'text', text: 'done'},
          {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 5, outputTokens: 5, totalTokens: 10}},
        ],
      ]),
      promptBuilder,
      registryReturning(),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seenUsage).toEqual({
      inputTokens: 15,
      outputTokens: 7,
      totalTokens: 22,
    });
  });
});

